const reps=[['0,0','1 · (0, 0)'],['1,0','3 · (1, 0)'],['0,1','3̄ · (0, 1)'],['2,0','6 · (2, 0)'],['0,2','6̄ · (0, 2)'],['1,1','8 · (1, 1)']];
const repSize=([p,q])=>(p+1)*(q+1)*(p+q+2)/2;
const repLabel=item=>item?.label||`(${item?.p??0}, ${item?.q??0})`;
